import{_ as o,o as a,c as d,a2 as t}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Windows 上那些“看起来像权限问题”的错误：进程边界、路径编码与入口后缀","description":"本地数据库起不来报的是 ACL 权限，真因却是安全策略禁止进程再创建 powershell 子进程；构建失败报的是文件找不到，真因是 URL().pathname 在 Windows 上多了一个前导斜杠和空格编码。","frontmatter":{"title":"Windows 上那些“看起来像权限问题”的错误：进程边界、路径编码与入口后缀","date":"2026-11-04T00:00:00.000Z","tags":["跨平台","Windows","排查","构建"],"description":"本地数据库起不来报的是 ACL 权限，真因却是安全策略禁止进程再创建 powershell 子进程；构建失败报的是文件找不到，真因是 URL().pathname 在 Windows 上多了一个前导斜杠和空格编码。"},"headers":[],"relativePath":"posts/windows-platform.md","filePath":"posts/windows-platform.md"}'),s={name:"posts/windows-platform.md"};function n(l,e,c,r,i,p){return a(),d("div",null,[...e[0]||(e[0]=[t(`<h1 id="windows-上那些-看起来像权限问题-的错误-进程边界、路径编码与入口后缀" tabindex="-1">Windows 上那些“看起来像权限问题”的错误：进程边界、路径编码与入口后缀 <a class="header-anchor" href="#windows-上那些-看起来像权限问题-的错误-进程边界、路径编码与入口后缀" aria-label="Permalink to &quot;Windows 上那些“看起来像权限问题”的错误：进程边界、路径编码与入口后缀&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>某 Agent 平台的本地开发环境跑在 Windows 上。本地数据库和桌面端入口要先过一道私密文件权限预检，预检内部会拉起 PowerShell 读 ACL；前端预览包构建则走另一条链。两轮排查下来，三处报错分别指向“权限不足”“文件找不到”“必须用包管理器启动”，看起来都像配置或权限问题，实际分属三个层面：进程创建、路径表示、外部契约。</p><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><ol><li>本地数据库启动脚本和桌面端入口都在预检处退出。日志只留下一行内部错误码和退出码 1。同一目录用 <code>Get-Acl</code> 手工看是正常的，三条允许规则看起来也对。自动化侧拉不起来，只能请用户在自己的终端执行。</li><li>前端预览包构建时报入口无法解析。日志打印的路径形如 <code>/D:/...%20...</code>：前面多一个斜杠，空格变成 <code>%20</code>。</li><li>包管理器升级后，启动准备的 CLI 标识校验不认新入口：旧入口是 <code>.cjs</code>/<code>.js</code>，新版是 <code>.mjs</code>。这条是读代码判定的，原始报错没有留下。</li></ol><h2 id="排查-从假设到证据" tabindex="-1">排查：从假设到证据 <a class="header-anchor" href="#排查-从假设到证据" aria-label="Permalink to &quot;排查：从假设到证据&quot;">​</a></h2><h3 id="一、先怀疑-acl-六步取证把它排除" tabindex="-1">一、先怀疑 ACL，六步取证把它排除 <a class="header-anchor" href="#一、先怀疑-acl-六步取证把它排除" aria-label="Permalink to &quot;一、先怀疑 ACL，六步取证把它排除&quot;">​</a></h3><p>我先怀疑目录 ACL 不合规：继承项混入、owner 不对、缺少允许主体。写了一个参数化取证脚本，按六步读：路径是否存在且为目录、是否 reparse point、当前用户 SID、目录 ACL 类型、owner SID 是否在允许集合、逐条规则打 OK/VIOLATION。</p><p>结果六步全 <code>ok</code>，<code>rule_count=3</code>。三条都是非继承的 Allow FullControl，主体分别是当前用户、SYSTEM、Administrators；owner 就是当前 SID；原始导出还证明父目录的继承项没有落到这个目录。<strong>ACL 合规，预检说的“权限不足”不是权限模型的事实。</strong></p><p>那问题只能在“读 ACL 的通道”上。先让 PowerShell 落一个标记文件，能写出来；再用 33 行最小脚本在 Node 里直接拉起 <code>powershell.exe</code>，带 <code>-NoProfile -NonInteractive</code>，15 秒超时。结果是 <code>SPAWN_FAIL / STATUS=null / CODE=EBUSY</code>，消息为 <code>spawnSync ...powershell.exe EBUSY</code>；该会话里 PowerShell 的 stdout 也不回显。</p><p>结论：不是没有权限读 ACL，而是<strong>当前进程树不允许再创建 PowerShell 子进程</strong>。预检拿不到输出，就把“通道失败”翻译成了“权限失败”。</p><h3 id="二、预加载补丁-能跑-但等于伪造校验" tabindex="-1">二、预加载补丁：能跑，但等于伪造校验 <a class="header-anchor" href="#二、预加载补丁-能跑-但等于伪造校验" aria-label="Permalink to &quot;二、预加载补丁：能跑，但等于伪造校验&quot;">​</a></h3><p>最省事的做法是用预加载补丁把校验 stub 掉，让启动先过去。评估后否决：预检的意义就是证明私密文件权限，绕过等于让启动在“未证明权限”的状态下继续。既然 ACL 已经合规，补丁唯一的作用是把环境限制藏起来。</p><p>最后保留 ACL 和校验不动，把启动动作移到不受限的终端。同一天 15:01，同一个最小复现返回 <code>SPAWN_OK</code>，项目自带的数据库脚本打印本地就绪回执；容器此前已 healthy，复用未重建。这说明差异在<strong>执行环境／进程树</strong>，不是代码回归。但策略按会话还是按进程树生效，我没有取证确认。</p><h3 id="三、构建失败-pathname-不是文件系统路径" tabindex="-1">三、构建失败：<code>.pathname</code> 不是文件系统路径 <a class="header-anchor" href="#三、构建失败-pathname-不是文件系统路径" aria-label="Permalink to &quot;三、构建失败：\`.pathname\` 不是文件系统路径&quot;">​</a></h3><p>先怀疑路径拼接错了：相对/绝对混用、分隔符写错。用 <code>pathToFileURL</code> 对同一文件复算，分别取 <code>.pathname</code> 和 <code>fileURLToPath</code>：前者得到 <code>/D:/...%20.../构建配置</code>，前导斜杠、盘符没去、空格被百分号编码；后者是正常的盘符路径。</p><p>再怀疑构建器对入口格式敏感。看报错确实落在入口和输出两处解析，把这两处改成 <code>fileURLToPath(new URL(...))</code> 后重跑，构建通过：121 个包，单次 191 秒。构建器无责。<code>URL.pathname</code> 返回的是 URL 路径段，不是文件系统路径；POSIX 下两者恰好同形，所以这段代码在 Linux/macOS 上“看起来能用”，只在 Windows 暴露。修复范围就是同一份构建配置里的两处。</p><h3 id="四、入口后缀-把文件名当成了版本契约" tabindex="-1">四、入口后缀：把文件名当成了版本契约 <a class="header-anchor" href="#四、入口后缀-把文件名当成了版本契约" aria-label="Permalink to &quot;四、入口后缀：把文件名当成了版本契约&quot;">​</a></h3><p>先怀疑包管理器调用方式失效（shell 引号、路径拆分）。读代码发现已经是 <code>shell:false</code>，并用 <code>process.execPath</code> 显式执行 CLI，避免 cmd.exe 拆分含空格路径——这是此前为 Windows 修过的，方向正确。</p><p>真正的问题是入口扩展名校验：旧白名单只认 <code>.cjs</code>/<code>.js</code>，新版入口是 <code>.mjs</code>，校验直接抛“必须经包管理器启动以提供 CLI 标识”。原意是“必须经包管理器启动”，实现却把入口文件名当成了版本契约。修复只是把正则补上 <code>mjs</code>，其余语义不动。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动 / 构建失败</span></span>
<span class="line"><span>├─ 预检报“权限不足”</span></span>
<span class="line"><span>│  ├─ 六步读 ACL ── 全 ok ──→ 不是权限模型</span></span>
<span class="line"><span>│  ├─ 直接 spawn PowerShell ── EBUSY ──→ 进程创建被拒</span></span>
<span class="line"><span>│  └─ 换执行位置 ── SPAWN_OK ──→ 环境边界，不是代码回归</span></span>
<span class="line"><span>├─ 构建报“入口无法解析”</span></span>
<span class="line"><span>│  ├─ 看报错路径 ── /D:/...%20... ──→ 是 URL 路径段</span></span>
<span class="line"><span>│  └─ 改 fileURLToPath ──→ 121 个包构建通过</span></span>
<span class="line"><span>└─ 预检不认 CLI</span></span>
<span class="line"><span>   ├─ 看调用方式 ── 已是 shell:false ──→ 调用无责</span></span>
<span class="line"><span>   └─ 看入口名 ── .mjs 不在白名单 ──→ 契约没跟上版本</span></span></code></pre></div><p>把三次放在一起看，区分环境与缺陷的顺序是：先看错误码属于谁——产品语义码还是 OS 错误码；再做最小复现矩阵，一次只减一个变量；最后问“不改代码，这个错误还能不能被解释”。ACL 六步取证加 spawn 复现，两条证据合起来才排除了权限问题；构建与入口后缀则是代码可解释、修复后即通过，且不依赖宿主策略，才判为产品缺陷。</p><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><ul><li><strong>进程边界</strong>：受限进程树里无法创建 PowerShell 子进程，<code>spawnSync</code> 返回 <code>EBUSY</code>、<code>status=null</code>。产品预检依赖“spawn 再解析输出”这条通道，通道一断就表现为权限校验失败。</li><li><strong>路径表示</strong>：<code>new URL(import.meta.url).pathname</code> 在 Windows 上返回带前导 <code>/</code>、盘符未去、空格百分号编码的 URL 路径段，被当成文件系统路径传给构建器。</li><li><strong>外部契约</strong>：包管理器升级改变了 CLI 入口扩展名，预检白名单没跟上；失败信息只说“要用包管理器启动”，指向性不足。</li></ul><p><strong>查到了什么：</strong> ACL 六步全 ok、3 条非继承 Allow、owner 正确、非 reparse；直接拉起 PowerShell 得到 <code>EBUSY/status=null</code>；换执行位置后 <code>SPAWN_OK</code>；两处 <code>.pathname</code> 改为 <code>fileURLToPath</code> 后 121 个包构建通过；白名单补 <code>mjs</code> 后启动准备 <code>success=true</code>。</p><p><strong>没查到什么：</strong> 15:01 恢复的具体成因没有取证，是按会话还是按进程树生效不清楚；没有在 CI、其他 Windows 版本、WSL 或容器里复验；没有跑 <code>test</code>／<code>typecheck</code>；191 秒、71.054 秒只是单次记录，不是稳定基线。</p><h2 id="修复方案与取舍" tabindex="-1">修复方案与取舍 <a class="header-anchor" href="#修复方案与取舍" aria-label="Permalink to &quot;修复方案与取舍&quot;">​</a></h2><ul><li>改 ACL 或放宽预检：否决。ACL 本来合规，改它只是迎合错误假设；放宽则让“私密文件不得被其他主体读取”的保证失效。</li><li>预加载补丁 stub 校验：否决。等于伪造安全校验结果，让真实缺陷无法暴露。</li><li>保留校验与 ACL，改执行位置：选择。代价是短期内自动化侧不能自动启动，需要人工一步。</li><li>手工 <code>replace(/^\\//, &#39;&#39;)</code> + <code>decodeURIComponent</code>：否决。只覆盖本次两种症状，遇到 <code>+</code>、<code>#</code>、UNC 或非 ASCII 还会错。改用 <code>fileURLToPath</code>，由标准库处理盘符、编码与平台差异。</li><li>继续 <code>shell:true</code> 加手工引号：否决。cmd.exe 的参数解析不可控。保留 <code>shell:false</code> 加 <code>process.execPath</code> 调 CLI，白名单补 <code>mjs</code>；代价是多一步 CLI 存在性判断。</li></ul><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>修复前</th><th>修复后</th><th>测量口径 / 环境</th></tr></thead><tbody><tr><td>本地数据库启动</td><td>预检失败，退出码 1</td><td>本地就绪回执</td><td>同一台 Windows、同一容器复用未重建；15:01 在新会话进程树执行</td></tr><tr><td>Node 创建 PowerShell 子进程</td><td><code>SPAWN_FAIL / STATUS=null / CODE=EBUSY</code></td><td><code>SPAWN_OK</code></td><td>33 行最小脚本，15 秒超时</td></tr><tr><td>ACL 合规判定</td><td>被判为“权限不足”</td><td>六步全 <code>ok</code>；3 条非继承 Allow；owner 正确</td><td>参数化取证脚本 + 原始 ACL 导出；只覆盖该目录</td></tr><tr><td>前端预览包构建</td><td>入口无法解析（<code>/D:/...%20...</code>）</td><td>成功，121 个包，单次 191 秒</td><td>本机 Windows；依赖重装后的首次全量</td></tr><tr><td>启动准备</td><td>不接受 <code>.mjs</code>（代码级判定）</td><td><code>success=true</code>，71.054 秒；build 复用 121 个产物、11.228 秒</td><td>单次运行产物，未取均值</td></tr></tbody></table><p>这张表必须和口径一起读：全部是单机、单次观测，不代表 macOS/ARM，也没有多次运行取均值；191 秒、71.054 秒是耗时记录，不是性能结论。修复后只表示本机构建和启动链路打通，<strong>没有跑自动化测试</strong>（<code>test</code>／<code>typecheck</code> 均未执行），不能写成功能验收或回归通过。问题一的“修复后”是执行位置调整加环境差异消失的结果，不是代码改动，也不能证明产品在受限进程树下同样能启动。没有在 CI 复现，没在其它 Windows 版本、WSL 或容器内复验。</p><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><p><strong>三条可迁移经验：</strong></p><ol><li>错误码的归属要和 OS 的事实对齐。产品抛的是业务语义码，OS 抛的是 <code>EBUSY/EPERM/EACCES</code>。先问一句：不改代码，这个错误还能不能被解释？能解释就是环境，解释不了才是缺陷。</li><li>最小复现要一次减一个变量，证据要落盘。换终端、换父进程、换机器、直接调 OS 原语；本例 PowerShell 的 stdout 被吞了，只能靠写文件取证。不要用“补丁能跑”当验证。</li><li>跨平台代码在 POSIX 上能跑，不代表正确。URL 路径段和文件系统路径是两套表示；外部契约（CLI 入口名、路径格式）要有契约测试，不能只测 happy path。</li></ol><p><strong>局限：</strong> 没查清进程策略为什么在 15:01 消失，也没能把这条差异搬进 CI。宿主策略、终端防护、沙箱这类不可复现的限制，只能靠 capability probe 记录并显式 skip，不允许静默通过；这部分我做到了记录，没做到自动化。</p>`,35)])])}const w=o(s,[["render",n]]);export{u as __pageData,w as default};
